package memory

import (
	"sync"
)

type Role string

const (
	RoleSystem    Role = "system"
	RoleUser      Role = "user"
	RoleAssistant Role = "assistant"
	RoleTool      Role = "tool"
)

// ToolCall represents a tool call generated by the model.
type ToolCall struct {
	ID        string
	Name      string
	Arguments string // JSON string
}

// Message represents a message in the conversation
// TODO: Refactor to sealed interface in a separate change
type Message struct {
	Role       Role       `json:"role"`
	Content    string     `json:"content"`
	ToolCallID string     `json:"tool_call_id,omitempty"` // For tool messages
	ToolCalls  []ToolCall `json:"tool_calls,omitempty"`   // For assistant messages
}

// Memory represents the thread-safe conversation timeline.
type Memory struct {
	mu          sync.RWMutex
	messages    []Message
	Inputs      map[string]interface{} // Workflow inputs
	NodeOutputs map[string]interface{} // Key: NodeID, Value: Output Data
	Variables   map[string]interface{} // Global variables
}

// NewMemory creates a new Memory with empty initial state.
func NewMemory() *Memory {
	return &Memory{
		messages:    make([]Message, 0),
		Inputs:      make(map[string]interface{}),
		NodeOutputs: make(map[string]interface{}),
		Variables:   make(map[string]interface{}),
	}
}

// NewGlobal creates a new Memory with initial messages.
func NewGlobal(initial []Message) *Memory {
	// Copy initial to avoid external mutation
	msgs := make([]Message, len(initial))
	copy(msgs, initial)
	return &Memory{
		messages:    msgs,
		Inputs:      make(map[string]interface{}),
		NodeOutputs: make(map[string]interface{}),
		Variables:   make(map[string]interface{}),
	}
}

// Append adds a message to the memory in a thread-safe manner.
func (m *Memory) Append(msg Message) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.messages = append(m.messages, msg)
}

// Snapshot returns a copy of the current messages.
// This is useful for creating local scopes or passing to LLMs.
func (m *Memory) Snapshot() []Message {
	m.mu.RLock()
	defer m.mu.RUnlock()

	snapshot := make([]Message, len(m.messages))
	copy(snapshot, m.messages)
	return snapshot
}

// Len returns the current number of messages.
func (m *Memory) Len() int {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return len(m.messages)
}

// SetNodeOutput stores the output of a node
func (m *Memory) SetNodeOutput(nodeID string, output interface{}) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.NodeOutputs[nodeID] = output
}

// GetNodeOutput retrieves the output of a node
func (m *Memory) GetNodeOutput(nodeID string) (interface{}, bool) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	val, ok := m.NodeOutputs[nodeID]
	return val, ok
}

// SetVariable stores a global variable
func (m *Memory) SetVariable(key string, value interface{}) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.Variables[key] = value
}

// GetVariable retrieves a global variable
func (m *Memory) GetVariable(key string) (interface{}, bool) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	val, ok := m.Variables[key]
	return val, ok
}

// SetInputs sets the workflow inputs
func (m *Memory) SetInputs(inputs map[string]interface{}) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.Inputs = inputs
}

// GetInputs retrieves the workflow inputs
func (m *Memory) GetInputs() map[string]interface{} {
	m.mu.RLock()
	defer m.mu.RUnlock()
	return m.Inputs
}

// GetCELContext returns a CEL evaluation context with inputs, nodes, and vars
func (m *Memory) GetCELContext() map[string]interface{} {
	m.mu.RLock()
	defer m.mu.RUnlock()

	return map[string]interface{}{
		"inputs": m.Inputs,
		"nodes":  m.NodeOutputs,
		"vars":   m.Variables,
	}
}
